package com.gympulse.app.data.repository

import com.gympulse.app.data.local.db.GymPulseDatabase
import com.gympulse.app.data.remote.api.GymPulseApi
import com.gympulse.app.data.sync.SyncEngine
import com.gympulse.app.data.sync.SyncError
import com.gympulse.app.domain.repository.DemoDataRepository
import java.io.IOException
import java.time.ZoneId
import javax.inject.Inject
import javax.inject.Singleton

/** Demonstration data is generated by the server, then pulled like any other data. */
@Singleton
class RemoteDemoDataRepository @Inject constructor(
    private val api: GymPulseApi,
    private val sync: SyncEngine,
    private val db: GymPulseDatabase,
) : DemoDataRepository {

    override suspend fun seedLibrary() = syncOrThrow()

    override suspend fun seedDemoContent() {
        syncOrThrow()
        api.seedDemo(ZoneId.systemDefault().id)
        syncOrThrow(includeHistory = true)
    }

    override suspend fun deleteDemoContent() {
        syncOrThrow()
        api.deleteDemo()
        syncOrThrow(includeHistory = true)
    }

    override suspend fun hasDemoContent(): Boolean = db.sessionDao().countDemo() > 0 || db.workoutDao().countDemo() > 0

    private suspend fun syncOrThrow(includeHistory: Boolean = false) {
        sync.sync(includeHistory)
        val error = sync.state.value.error
        if (error != null) throw SyncFailedException(error)
    }
}

class SyncFailedException(val error: SyncError) : IOException("Synchronisation failed: $error")
